widget.solution:
import math

def days_to_fraction(phi, frac):
    if abs(phi) >= 1:
        return math.inf                      # no decay: never gets there
    if phi == 0:
        return 0.0                           # gone after one step
    return math.log(frac) / math.log(abs(phi))   # |phi| for the size of the deviation

def half_life(phi):
    return days_to_fraction(phi, 0.5)

