import numpy as np

def make_ar1(phi, n, seed, c=0.0):
    """Seeded AR(1): x_t = c + phi * x_{t-1} + e_t, e_t ~ N(0, 1), x_0 = e_0."""
    e = np.random.default_rng(seed).standard_normal(n)
    x = np.empty(n)
    x[0] = e[0]
    for t in range(1, n):
        x[t] = c + phi * x[t - 1] + e[t]
    return x

def make_walk(seed, n=500, drift=0.0):
    """Seeded random walk from 0: x_t = x_{t-1} + drift + e_t, e_t ~ N(0, 1)."""
    e = np.random.default_rng(seed).standard_normal(n)
    return np.cumsum(drift + e)

def make_wn(seed, n=500):
    """Seeded white noise: n independent N(0, 1) draws."""
    return np.random.default_rng(seed).standard_normal(n)

def make_arma(phis, thetas, n, seed, burn=200):
    """Seeded ARMA: x_t = e_t + sum_i phi_i x_{t-i} + sum_j theta_j e_{t-j},
    e_t ~ N(0, 1); the first burn values are dropped."""
    e = np.random.default_rng(seed).standard_normal(n + burn)
    x = np.zeros(n + burn)
    for t in range(n + burn):
        v = e[t]
        for i, phi in enumerate(phis, start=1):
            if t - i >= 0:
                v += phi * x[t - i]
        for j, theta in enumerate(thetas, start=1):
            if t - j >= 0:
                v += theta * e[t - j]
        x[t] = v
    return x[burn:]

def make_pair(seed, n=1000, alpha=5.0, beta=1.5, phi=0.95, sd_u=0.5, x0=40.0, vol=0.015):
    """x: a share price from x0 in pounds, log random walk with daily sd vol.
    y = alpha + beta * x + u, u an AR(1) with coefficient phi and innovation sd sd_u."""
    z = np.random.default_rng(seed).standard_normal((n, 2))
    x = x0 * np.exp(np.cumsum(vol * z[:, 0]))
    u = np.empty(n); u[0] = sd_u * z[0, 1]
    for t in range(1, n): u[t] = phi * u[t-1] + sd_u * z[t, 1]
    return x, alpha + beta * x + u

