import math
import numpy as np

def half_life_from_series(x):
    x = np.asarray(x, dtype=float)
    dx = np.diff(x)                                   # Δx_t
    X = np.column_stack([np.ones(len(dx)), x[:-1]])   # constant and x_{t-1}
    a, b = np.linalg.lstsq(X, dx, rcond=None)[0]
    if b >= 0:
        return math.inf                               # phi >= 1: no reversion
    return math.log(0.5) / math.log(1 + b)

